$ cat Unload.java
public class Unload {
    static Object strongRef;          // 붙잡아 두는 자리
    public static void main(String[] a) throws Exception {
        Path dir = Paths.get(a[0]);
        boolean leak = a.length > 1 && a[1].equals("leak");

        URLClassLoader cl = new URLClassLoader("tmp",
            new URL[]{ dir.toUri().toURL() }, null);
        Class<?> c = cl.loadClass("Solo");
        if (leak) strongRef = c;      // Class 객체 하나만 붙잡는다

        cl.close(); cl = null; c = null;
        for (int i = 0; i < 3; i++) { System.gc(); Thread.sleep(200); }
    }
}

# --- 1) 안 붙잡으면 ---

$ java -Xlog:class+unload=info -cp . Unload .
  로더로 Solo 를 읽었다: tmp
  참조를 끊고 GC 를 부른다
